    // 1. 触发词定义
    var PAYLOAD_PROLOGUE = decodeURIComponent('%5B%E6%80%AA%E8%B0%88%E7%A4%BE%C2%B7%E4%BB%AA%E5%BC%8F%E5%BC%80%E5%90%AF%EF%BC%9A%E5%90%AF%E5%B0%81%E5%88%9D%E9%81%87%5D');
    var PAYLOAD_NIGHT = decodeURIComponent('%5B%E6%80%AA%E8%B0%88%E7%A4%BE%C2%B7%E4%BB%AA%E5%BC%8F%E5%BC%80%E5%90%AF%EF%BC%9A%E9%80%A2%E9%AD%94%E7%85%A7%E5%A4%9C%5D');

    // 2. 动态高度自适应
    var resizeTimer = null;
    function reportCoverHeight() {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(function() {
            var h = document.body.scrollHeight;
            if (window.parent) {
                window.parent.postMessage({ type: 'iframe-resize', height: h, source: 'kaidan-cover-v5' }, '*');
                window.parent.postMessage({ type: 'resizeIframe', height: h }, '*');
            }
            try {
                if (window.frameElement) window.frameElement.style.height = h + 'px';
            } catch(e) {}
        }, 50);
    }
    if (window.ResizeObserver) new ResizeObserver(reportCoverHeight).observe(document.body);
    window.addEventListener('load', reportCoverHeight);

    // 3. MVU 直写引擎
    async function directCommitMvu(mutations) {
        try {
            var Mvu = window.Mvu || (window.parent && window.parent.Mvu) || (window.top && window.top.Mvu);
            if (!Mvu) return;
            var mvuData = Mvu.getMvuData({ type: 'message', message_id: -1 });
            if (!mvuData) return;

            var _set = (window._ && window._.set) || (window.parent && window.parent._ && window.parent._.set) || function(obj, path, val) {
                var parts = path.split('.');
                var curr = obj;
                for (var i = 0; i < parts.length - 1; i++) {
                    if (!curr[parts[i]]) curr[parts[i]] = {};
                    curr = curr[parts[i]];
                }
                curr[parts[parts.length - 1]] = val;
            };

            for (var path in mutations) {
                _set(mvuData, path, mutations[path]);
            }

            await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: -1 });

            var $ = window.$ || (window.parent && window.parent.$) || (window.top && window.top.$);
            if (Mvu.events && $) {
                var payload = { stat_data: mvuData.stat_data || mvuData };
                $(document).trigger({ type: Mvu.events.VARIABLE_UPDATE_ENDED, detail: payload });
                if (window.parent) $(window.parent.document).trigger({ type: Mvu.events.VARIABLE_UPDATE_ENDED, detail: payload });
            }
        } catch (e) {
            console.error('[MVU Direct Commit Error]', e);
        }
    }

    // 4. 工作流驱动
    async function triggerWorkflow(cardElement, labelElement, textToSend, mvuMutations) {
        if (cardElement.getAttribute('data-active') === '1') return;
        cardElement.setAttribute('data-active', '1');
        cardElement.classList.add('busy');
        var prevLabel = labelElement.innerHTML;
        labelElement.innerHTML = '<span>❖</span> 启封中…';

        if (mvuMutations) {
            await directCommitMvu(mvuMutations);
        }

        var mainDoc = document;
        if (window.parent && window.parent.document) mainDoc = window.parent.document;
        else if (window.top && window.top.document) mainDoc = window.top.document;

        var inputArea = mainDoc.getElementById('send_textarea');
        var submitBtn = mainDoc.getElementById('send_but');

        if (inputArea && submitBtn) {
            var descriptor = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value');
            var nativeSetter = descriptor ? descriptor.set : null;
            if (nativeSetter) nativeSetter.call(inputArea, textToSend);
            else inputArea.value = textToSend;

            inputArea.dispatchEvent(new Event('input', { bubbles: true }));
            inputArea.dispatchEvent(new Event('change', { bubbles: true }));
            inputArea.focus();
            setTimeout(function() {
                submitBtn.click();
            }, 200);
        } else {
            console.warn('[怪谈社] 无法获取酒馆输入框或发送按键');
            setTimeout(function() {
                cardElement.removeAttribute('data-active');
                cardElement.classList.remove('busy');
                labelElement.innerHTML = prevLabel;
            }, 1000);
        }
    }

    // 5. 事件绑定
