        { date: "6月14日", id: 614, event: "期中考试周" }, { date: "6月21日", id: 621, event: "夏至" },
        { date: "7月7日", id: 707, event: "七夕" }, { date: "7月15日", id: 715, event: "泳池开启日" },
        { date: "7月25日", id: 725, event: "暑假开始" }, { date: "8月8日", id: 808, event: "夏日花火大会" },
        { date: "8月13日", id: 813, event: "盂兰盆节" }, { date: "8月20日", id: 820, event: "暑期林间学校" },
        { date: "8月26日", id: 826, event: "社团合宿解散日" }, { date: "8月31日", id: 831, event: "暑假最后一天" },
        { date: "9月1日", id: 901, event: "开学典礼" }, { date: "9月15日", id: 915, event: "体育祭" },
        { date: "9月29日", id: 929, event: "赏月会" }
    ];

    const getSortWeight = (id) => {
        const m = Math.floor(id / 100); const d = id % 100;
        return (m >= 10 ? m - 10 : m + 2) * 100 + d;
    };

    function toKanjiNumber(n) {
        n = Math.min(100, Math.max(0, Math.floor(n)));
        const d = ['零','一','二','三','四','五','六','七','八','九'];
        if (n <= 9) return d[n];
        if (n === 100) return '百';
        const tens = Math.floor(n / 10); const ones = n % 10;
        return (tens === 1 ? '十' : d[tens] + '十') + (ones ? d[ones] : '');
    }

    async function getSnapshotData() {
        let isHistorical = false;
        try {
            const msgId = typeof getCurrentMessageId === 'function' ? getCurrentMessageId() : -1;
            if (msgId !== -1 && typeof getChatMessages === 'function') {
                const msgs = await getChatMessages(msgId, 1);
                const chatArray = window.chat || (window.parent && window.parent.chat) || (window.top && window.top.chat) || [];
                isHistorical = (msgId < (chatArray.length > 0 ? chatArray.length - 1 : -1));
                if (msgs && msgs[0] && msgs[0].data) return { data: JSON.parse(JSON.stringify(msgs[0].data)), isHistorical };
            }
            const Mvu = window.Mvu || (window.parent && window.parent.Mvu) || (window.top && window.top.Mvu);
            if (Mvu) return { data: JSON.parse(JSON.stringify(Mvu.getMvuData({ type: 'message', message_id: -1 }) || {})), isHistorical: false };
        } catch (e) { console.warn("[Lantern] Snapshot error", e); }
        return { data: {}, isHistorical };
    }

    let resizeTimer = null;
    function reportHeight() {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(() => {
            const wrapper = document.querySelector('.lantern-wrapper');
            const h = wrapper ? wrapper.offsetHeight + 10 : document.body.scrollHeight;
            if (window.parent) {
                window.parent.postMessage({ type: 'iframe-resize', height: h, source: 'lantern-ui' }, '*');
                window.parent.postMessage({ type: 'resizeIframe', height: h }, '*');
            }
            try { if (window.frameElement) window.frameElement.style.height = h + 'px'; } catch(e) {}
        }, 50);
    }
    window.__lanternRO = new ResizeObserver(() => reportHeight());
    window.__lanternRO.observe(document.body);

    async function updateMvuVar(path, value) {
        try {
            const Mvu = window.Mvu || (window.parent && window.parent.Mvu) || (window.top && window.top.Mvu);
            if (!Mvu) return;
            const mvuData = Mvu.getMvuData({ type: 'message', message_id: -1 });
            if (!mvuData) return;
            if (typeof _ !== 'undefined' && _.set) _.set(mvuData, path, value);
            await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: -1 });
            if (Mvu.events && typeof $ !== 'undefined') {
                $(document).trigger({ type: Mvu.events.VARIABLE_UPDATE_ENDED, detail: { stat_data: mvuData.stat_data || mvuData } });
            }
        } catch (e) { console.error("[Lantern Update]", e); }
    }

    let isTutorialCompleted = false;

    function applyPhase($shell, $stage, $lantern, phase, isTutorialDone, currentMP, isHistorical) {
      $lantern.removeClass('flame-lit flame-haunted mp-5 mp-4 mp-3 mp-2 mp-critical interactive member-ready tutorial-sealed'); 
      $stage.removeClass('interactive');
      $shell.removeClass('haunted-glow');
      isTutorialCompleted = !!isTutorialDone;

      if (!isHistorical && (phase === '日常' || phase === '结算')) {
          $stage.addClass('interactive');
          $lantern.addClass('interactive');
          if (isTutorialDone) {
              $lantern.addClass('member-ready').attr('title', '点击点亮青行灯 (推进剧情)');
          } else {
              $lantern.addClass('tutorial-sealed').attr('title', '青行灯尚未注灵（封印中）');
          }
      } else { 
          $lantern.attr('title', ''); 
      }

      if (phase === '导入') $lantern.addClass('flame-lit');
      if (phase === '怪谈') { 
          $lantern.addClass('flame-haunted'); $shell.addClass('haunted-glow');
          if (currentMP >= 5) $lantern.addClass('mp-5');
          else if (currentMP === 4) $lantern.addClass('mp-4');
          else if (currentMP === 3) $lantern.addClass('mp-3');
          else if (currentMP === 2) $lantern.addClass('mp-2');
          else $lantern.addClass('mp-critical');
      }
      reportHeight();
    }

    function handleLanternClick() {
        if (!isTutorialCompleted) {
            $('#lantern-stage').removeClass('shake');
            void document.getElementById('lantern-stage').offsetWidth;
            $('#lantern-stage').addClass('shake');

            $('#modal-desc-text').html('青行灯静默无声。<br>你尚未通过入部试炼，无法唤醒幽火。<br><span style="color:#888; font-size:11.5px;">（请先与长椅上的绮罗香完成对话）</span>');
            $('#btn-modal-cancel').text('明白').show();
            $('#btn-modal-confirm').hide(); 
            $('#confirm-modal').addClass('show');
            reportHeight();
            return;
        }

        $('#modal-desc-text').html('即将跳过当前时间<br>并开始下一次社团怪谈活动。<br><span style="color:#a62626; font-size:12px;">（将自动推进剧情）</span>');
        $('#btn-modal-cancel').text('犹豫').show();
        $('#btn-modal-confirm').text('点亮').show();
        $('#confirm-modal').addClass('show'); 
        reportHeight(); 
    }

    function hideConfirm() { $('#confirm-modal').removeClass('show'); reportHeight(); }

    async function executeNextStory() {
        hideConfirm();
        await updateMvuVar('stat_data.游戏状态.当前阶段', '导入');
        await updateMvuVar('stat_data.游戏状态.当前怪谈标题', '（未知怪谈）'); 
        await updateMvuVar('stat_data.白物语注册表', {}); 
        $('#phase-text').text('青行灯被点亮');
        $('#lantern-stage').removeClass('interactive');
        $('#lantern-core').removeClass('interactive member-ready tutorial-sealed').addClass('flame-lit');

        const findEl = (id) => {
            let el = document.getElementById(id);
            if (!el && window.parent && window.parent.document) el = window.parent.document.getElementById(id);
            return el;
        };
        const textarea = findEl('send_textarea');
        const sendBtn = findEl('send_but');
        const text = "很快，下一次社团活动的时间到了。";
        if (textarea && sendBtn) {
            const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, "value")?.set;
            if (nativeSetter) nativeSetter.call(textarea, text); else textarea.value = text;
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
            textarea.dispatchEvent(new Event('change', { bubbles: true }));
            textarea.focus();
            setTimeout(() => sendBtn.click(), 250);
        }
    }

    function populateStatus(data, isHistorical) {
      if (typeof $ === 'undefined' || typeof _ === 'undefined') return;
      const all = data || {};

      const phase = _.get(all, 'stat_data.游戏状态.当前阶段', '日常');
      const title = _.get(all, 'stat_data.游戏状态.当前怪谈标题', '无');
      const isTutorialDone = _.get(all, 'stat_data.游戏状态.新手引导已完成', false);
      const isSaeRevealed = _.get(all, 'stat_data.游戏状态.沙绘已登场', false);
      const currentMP = _.get(all, 'stat_data.玩家状态.灵力', 5);

      const env = _.get(all, 'stat_data.环境状态', {});
      const location = env.当前地点 || '怪谈社活动室';
      const isKiragaPresent = _.get(env, '在场角色.白川绮罗香', true);
      const isSaePresent = _.get(env, '在场角色.绪川沙绘', false);

      $('#env-location-text').text(location);
      $('#kata-kiraga').toggleClass('active', isKiragaPresent).toggleClass('absent', !isKiragaPresent);

      if (isSaePresent) {
          $('#kata-sae').addClass('active').removeClass('absent').show();
      } else {
          $('#kata-sae').removeClass('active').addClass('absent');
          if (!isSaeRevealed) $('#kata-sae').hide(); else $('#kata-sae').show();
      }

      $('#lantern-shell').toggleClass('historical-snapshot', isHistorical);

      const isPeace = (phase === '日常' || phase === '结算');
      $('#spirit-bar-container').toggleClass('phase-collapse', isPeace);

      let phaseDisplay = '';
      if (phase === '日常') {
          phaseDisplay = isTutorialDone ? '仪式尚未开始' : '入部届前';
      } else if (phase === '导入') {
          phaseDisplay = '青行灯被点亮';
      } else if (phase === '怪谈') {
          phaseDisplay = '怪谈正在回应';
      } else {
          phaseDisplay = '记录即将封存';
      }
      $('#phase-text').text(phaseDisplay);

      const shouldShowTitle = title && title !== '无' && title.trim() !== '';
      if (shouldShowTitle) $('#title-text').text(`《${title}》`).removeClass('phase-collapse');
      else $('#title-text').text('').addClass('phase-collapse');

      applyPhase($('#lantern-shell'), $('#lantern-stage'), $('#lantern-core'), phase, isTutorialDone, currentMP, isHistorical);

      // 灵力点
      const $mpContainer = $('#spirit-bar');
      $mpContainer.empty();
      for (let i = 0; i < 5; i++) {
          $mpContainer.append(`<div class="hitodama ${i < currentMP ? 'active' : ''}"></div>`);
      }
      $('#mp-label').text(currentMP <= 0 ? "灵力耗尽" : "言灵力");

      // ================= 🎴 抽屉一渲染 =================
      const pendingEvents = _.get(all, 'stat_data.系统状态.待处理事件', {});

      // 1. 白川绮罗香
      const favor = _.get(all, 'stat_data.角色状态.白川绮罗香.好感度', 0);
      const kiragaLevel = Math.min(3, Math.max(0, _.get(all, 'stat_data.角色状态.白川绮罗香.好感度等级', 0)));
      const kCap = [20, 50, 80, 100][kiragaLevel] || 100;
      let kRankUp = (!isHistorical && lastKiragaLevel >= 0 && kiragaLevel > lastKiragaLevel);
      if (!isHistorical) lastKiragaLevel = kiragaLevel;

      $('#res-fill-kiraga').css('width', Math.min((favor / kCap) * 100, 100) + '%');
      $('#kiraga-name-display').html(`白川 绮罗香 <span class="bond-title ${kRankUp ? 'rankup' : ''}">${KIRAGA_TITLES[kiragaLevel]}</span>`);
      $('#kiraga-num-display').text(`${favor} / ${kCap}`);

      const kBottleneck = pendingEvents['系统_好感瓶颈'];
      if (kBottleneck) {
          $('#kiraga-sub-hint').text(`“${kBottleneck}”`).show();
      } else {
          $('#kiraga-sub-hint').text('').hide();
      }

      // 2. 绪川沙绘
      const saeFavor = _.get(all, 'stat_data.角色状态.绪川沙绘.好感度', 0);
      const saeLevel = Math.min(3, Math.max(0, _.get(all, 'stat_data.角色状态.绪川沙绘.好感度等级', 0)));
      const sCap = [30, 60, 90, 100][saeLevel] || 100;
      if (!isSaeRevealed) {
          $('#sae-name-display').html(`<span style="color:#666;">??? (指导老师)</span>`);
          $('#sae-num-display').text(`? / ?`);
          $('#res-fill-sae').css('width', '0%');
          $('#sae-sub-hint').text('').hide();
          if (!isHistorical) lastSaeLevel = -1;
      } else {
          let sRankUp = (!isHistorical && lastSaeLevel >= 0 && saeLevel > lastSaeLevel);
          if (!isHistorical) lastSaeLevel = saeLevel;

          $('#res-fill-sae').css('width', Math.min((saeFavor / sCap) * 100, 100) + '%');
          $('#sae-name-display').html(`绪川 沙绘 <span class="bond-title ${sRankUp ? 'rankup' : ''}">${SAE_TITLES[saeLevel]}</span>`);
          $('#sae-num-display').text(`${saeFavor} / ${sCap}`);

          const sBottleneck = pendingEvents['系统_沙绘瓶颈'];
          if (sBottleneck) {
              $('#sae-sub-hint').text(`“${sBottleneck}”`).show();
          } else {
              $('#sae-sub-hint').text('').hide();
          }
      }

      // ================= 📜 抽屉二渲染 =================
      const archives = _.get(all, 'stat_data.档案库.已完成怪谈', {});
      const solvedCount = Object.keys(archives).length;

      // 1. 典雅标题：0篇时叫“等待启封”，有怪谈后才称“第X夜”
      if (solvedCount === 0) {
          $('#archive-stats').html(
              '<div class="archive-title">物語：等待启封</div>' +
              '<div class="archive-sub">百物语 · 卷首空白</div>'
          );
      } else {
          $('#archive-stats').html(
              `<div class="archive-title">物語 · 第${toKanjiNumber(solvedCount)}夜 <span style="font-size:10px; font-family:monospace; opacity:0.6; font-weight:normal;">[ ${solvedCount}/100 ]</span></div>` +
              `<div class="archive-sub">已封存 ${solvedCount} 柱怪谈</div>`
          );
      }

      // 2. 列表渲染或清爽空白扉页
      let newArchiveHtml = '';
      if (solvedCount === 0) {
          newArchiveHtml = 
              '<div class="archive-empty-leaf">' +
                  '<div class="empty-leaf-text">纸页尚白，待青灯照夜</div>' +
              '</div>';
          $('#souvenir-detail').hide();
      } else {
          Object.entries(archives).forEach(([t, rec]) => {
              const sName = encodeURIComponent(rec.纪念品名称 || "");
              const sDesc = encodeURIComponent(rec.纪念品描述 || "");
              newArchiveHtml += `<div class="seal-dossier" data-title="${t}" data-sname="${sName}" data-sdesc="${sDesc}"><span style="letter-spacing:1px; z-index:1;">${t}</span><span class="seal-stamp">封</span></div>`;
          });
      }

      if ($('#archive-scroll').html() !== newArchiveHtml) {
          $('#archive-scroll').html(newArchiveHtml);

          // 3. 奇物展柜点击联动
          $('.seal-dossier').off('click').on('click', function() {
              const wasActive = $(this).hasClass('active-dossier');
              $('.seal-dossier').removeClass('active-dossier');
              $('#souvenir-detail').hide();

              if (!wasActive) {
                  $(this).addClass('active-dossier');
                  const name = decodeURIComponent($(this).attr('data-sname') || "");
                  const desc = decodeURIComponent($(this).attr('data-sdesc') || "");

                  if (name) {
                      $('#sv-title').text('纪念品：' + name);
                      $('#sv-desc').text(desc || "此物留于活动室中，气息已归于平静。");
                  } else {
                      $('#sv-title').text('无残留之物');
                      $('#sv-desc').text('异化消散，未在现世留下痕迹。');
                  }
                  $('#souvenir-detail').show();
              }
              reportHeight();
          });
      }

      // ================= 🍂 抽屉三渲染 =================
      const dateStr = _.get(all, 'stat_data.日历.当前日期', '10月2日');
      const mMatch = dateStr.match(/(\d+)\s*月\s*(\d+)/);
      let month = 10, day = 2;
      if (mMatch) { month = parseInt(mMatch[1]); day = parseInt(mMatch[2]); }
      const year = (month >= 4 && month <= 12) ? 2024 : 2025;
      const currentDateObj = new Date(year, month - 1, day);
      const weekDays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
      const currentWeekDay = weekDays[currentDateObj.getDay()];

      function getDayStatus(y, m, d) {
          const wd = new Date(y, m - 1, d).getDay(); const md = m * 100 + d;
          if (md >= 725 && md <= 831) return { rest: true, type: "暑假" };
          if (md >= 1225 || md <= 107) return { rest: true, type: "寒假" };
          if (md >= 325 && md <= 405) return { rest: true, type: "春假" };
          if (md >= 429 && md <= 505) return { rest: true, type: "黄金周" };
          if ([101, 211, 223, 320, 811, 1103, 1123].includes(md)) return { rest: true, type: "法定假日" };
          if (wd === 0 || wd === 6) return { rest: true, type: "周末" };
          return { rest: false, type: "平日" };
      }
      const todayStatus = getDayStatus(year, month, day);

      let seasonConfig;
      if (month >= 3 && month <= 5) {
          seasonConfig = { text: "春季", color: "#f48fb1", haiku: "春寒入夜半<br>笔尖轻颤字未干<br>花落掩旧坛" };
      } else if (month >= 6 && month <= 8) {
          seasonConfig = { text: "夏季", color: "#4dd0e1", haiku: "骤雨暗回廊<br>青灯摇曳影惊墙<br>蝉泣送斜阳" };
      } else if (month >= 9 && month <= 11) {
          seasonConfig = { text: "秋季", color: "#dfa668", haiku: "秋风翻旧卷<br>谁人低语在耳畔<br>回头却不见" };
      } else {
          seasonConfig = { text: "冬季", color: "#81d4fa", haiku: "雪夜掩重门<br>炉火微温伴孤魂<br>闲话了无痕" };
      }

      $('#cal-haiku-display').html(seasonConfig.haiku);
      $('#cal-season-display').text(seasonConfig.text).css({ 'color': seasonConfig.color, 'border-color': seasonConfig.color + '50' });
      $('#cal-date-display').text(dateStr + " " + currentWeekDay);

      const currentWeight = getSortWeight(month * 100 + day);
      let nextEvent = SCHOOL_CALENDAR.find(e => getSortWeight(e.id) >= currentWeight) || SCHOOL_CALENDAR[0];
      const $eventBox = $('#cal-event-box');
      if (nextEvent.id === (month * 100 + day)) {
          $eventBox.css('--season-color', '#ffca28');
          $('#cal-event-badge').html(`<span style="color:#ffca28;">◆ 今日事件</span>`);
      } else {
          $eventBox.css('--season-color', seasonConfig.color);
          const tarMonth = Math.floor(nextEvent.id / 100); const tarDay = nextEvent.id % 100;
          const targetYear = (tarMonth < 4 && year === 2024) ? 2025 : (tarMonth >= 4 && year === 2025) ? 2024 : year; 
          let dayDiff = Math.ceil((new Date(targetYear, tarMonth - 1, tarDay) - currentDateObj) / (1000 * 60 * 60 * 24));
          if (dayDiff < 0) dayDiff += 365;
          $('#cal-event-badge').html(`距今 <span style="color:${seasonConfig.color};">${dayDiff > 60 ? "未来日程" : `${dayDiff} 天后`}</span>`);
      }
      $('#cal-next-event').text(nextEvent.event);

      let nextHolidayStr = "";
      if (todayStatus.rest) {
          nextHolidayStr = `>>> 今日休息（${todayStatus.type}） <<<`;
      } else {
          for (let d = 1; d <= 7; d++) {
              let tDate = new Date(year, month - 1, day + d);
              let chk = getDayStatus(tDate.getFullYear(), tDate.getMonth() + 1, tDate.getDate());
              if (chk.rest) {
                  nextHolidayStr = d === 1 ? `预告：明日休息（${chk.type}）` : `距下个休息日还有 ${d} 天`;
                  break;
              }
          }
      }
      $('#cal-holiday-preview').text(nextHolidayStr || "近期暂无假日");

      // 关键词言灵日志
      const $kw = $('#drawer-keywords');
      const registry = _.get(all, 'stat_data.白物语注册表', {});
      const entries = Object.entries(registry);
      if (entries.length > 0 || phase === '怪谈') {
          $kw.addClass('open');
          $kw.empty();
          if (entries.length === 0) {
              $kw.append('<div style="text-align:center; color:#555; font-size:11px;">等待言灵改写...</div>');
          } else {
              entries.forEach(([oldW, d]) => {
                  $kw.append(`<div class="log-row"><span class="word-old">${oldW}</span><span style="color:#8f2626; margin:0 6px;">➜</span><span class="word-new">${d.改写后文本 || "???"}</span></div>`);
              });
          }
      } else {
          $kw.removeClass('open').empty();
      }

      reportHeight();
    }

    function toggleDrawer(id, btnId) {
        const $target = $(id); const isOpen = $target.hasClass('open');
        $('.drawer').removeClass('open'); $('.vent-btn').removeClass('active');
        if (!isOpen) { $target.addClass('open'); $(btnId).addClass('active'); }
        reportHeight();
    }

    async function init() {
      if (typeof $ === 'undefined' && window.parent && window.parent.$) window.$ = window.parent.$;
      if (typeof _ === 'undefined' && window.parent && window.parent._) window._ = window.parent._;
      const snapshotInfo = await getSnapshotData();

      $('#btn-resonance').off('click').on('click', () => toggleDrawer('#drawer-resonance', '#btn-resonance'));
      $('#btn-seal').off('click').on('click', () => toggleDrawer('#drawer-seal', '#btn-seal'));
      $('#btn-calendar').off('click').on('click', () => toggleDrawer('#drawer-calendar', '#btn-calendar'));

      if (!snapshotInfo.isHistorical) {
          $('#lantern-stage').off('click').on('click', function(e) {
              e.stopPropagation();
              handleLanternClick();
          });
          $('#btn-modal-cancel').off('click').on('click', hideConfirm);
          $('#btn-modal-confirm').off('click').on('click', executeNextStory);
      }

      populateStatus(snapshotInfo.data, snapshotInfo.isHistorical);
      reportHeight();
    }

    $(init);
  </script>
</head>

