import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  // --- 1. 游戏主控流程 ---
  游戏状态: z.object({
    当前阶段: z.enum(['日常', '导入', '怪谈', '结算']).default('日常'),
    当前怪谈标题: z.string().default('无'),
    新手引导已完成: z.boolean().default(false),
    沙绘已登场: z.boolean().default(false) 
  }).prefault({ 
    当前阶段: '日常', 
    当前怪谈标题: '无', 
    新手引导已完成: false,
    沙绘已登场: false 
  }),

  // --- 2. 事件推送系统 ---
  系统状态: z.object({
    待处理事件: z.record(z.string(), z.any()).default({}) 
  }).prefault({
    待处理事件: {}
  }),

  // --- 3. 角色数值 ---
  角色状态: z.object({
    白川绮罗香: z.object({
      好感度: z.number().default(0),  
      好感度等级: z.number().default(0)   
    }).default({好感度: 0, 好感度等级: 0}), 

    绪川沙绘: z.object({
      好感度: z.number().default(0),
      好感度等级: z.number().default(0) 
    }).default({好感度: 0, 好感度等级: 0})  
  }).prefault({ 
    白川绮罗香: {好感度: 0, 好感度等级: 0},
    绪川沙绘: {好感度: 0, 好感度等级: 0}
  }),

  玩家状态: z.object({
    灵力: z.number().max(5).min(0).default(5)
  }).prefault({ 灵力: 5 }),

  // --- 4. 核心玩法：白物语改写 ---
  白物语注册表: z.record(
    z.string(), 
    z.object({
      改写后文本: z.string(),
      是否锁定: z.boolean().default(true)
    })
  ).default({}),

  // --- 5. 时间与环境系统 ---
  日历: z.object({
    当前日期: z.string().default("10月2日")
  }).prefault({ 当前日期: "10月2日" }),

  环境状态: z.object({
    当前地点: z.string().default("怪谈社活动室"),
    在场角色: z.object({
      白川绮罗香: z.boolean().default(true),
      绪川沙绘: z.boolean().default(false)
    }).default({ 白川绮罗香: true, 绪川沙绘: false })
  }).prefault({ 
    当前地点: "怪谈社活动室",
    在场角色: { 白川绮罗香: true, 绪川沙绘: false }
  }),

  // --- 6. 收集与档案 ---
  档案库: z.object({
    已完成怪谈: z.record(z.string(), z.any()).default({})
  }).default({ 
    已完成怪谈: {} 
  }).prefault({ 
    已完成怪谈: {}
  })
});

$(() => { registerMvuSchema(Schema); });

/**
 * [v12.3] 交互选项
 */

const OPTION_REGEX = /【([^】]+)】/g;
const SCAN_DELAY = 200; 

// --- 1. CSS 样式与特效注入 ---
function injectStyles() {
    try {
        const topDoc = window.top.document;
        if (topDoc.getElementById('interactive-options-style-v12')) return;

        const oldStyle = topDoc.getElementById('interactive-options-style-v11');
        if (oldStyle) oldStyle.remove();

        const style = topDoc.createElement('style');
        style.id = 'interactive-options-style-v12';
        style.textContent = `
            .interactive-option-btn {
                background-color: #f5e8c8; color: #a62626; border: 1px solid #7d1c1c;
                padding: 4px 12px; margin: 0 4px; border-radius: 4px;
                cursor: pointer; font-size: 14px; font-weight: bold;
                font-family: 'serif', 'SimSun', 'MS Mincho'; 
                transition: all 0.15s ease-out;
                box-shadow: 2px 2px 4px rgba(0,0,0,0.2); 
                display: inline-block; line-height: 1.5; vertical-align: middle;
                position: relative; z-index: 10; pointer-events: auto; user-select: none;
            }
            .interactive-option-btn:hover {
                transform: translateY(-2px); box-shadow: 0 4px 8px rgba(166, 38, 38, 0.3); 
                border-color: #ff0000; background-color: #fffdf5; color: #d63031;
            }
            .interactive-option-btn.smashed {
                pointer-events: none;
                color: #5c1818 !important; background: #1a0505 !important; border-color: #8f2626 !important;
                box-shadow: 0 0 15px rgba(255, 0, 0, 0.8), inset 0 0 10px rgba(0,0,0,0.8) !important;
                text-decoration: line-through 3px #ff0000;
                animation: glass-shatter 0.35s cubic-bezier(.36,.07,.19,.97) forwards;
            }
            @keyframes glass-shatter {
                0% { transform: scale(1); filter: brightness(2); }
                20% { transform: scale(1.15) skewX(-15deg); filter: contrast(2) blur(1px); color: #ff0000; }
                100% { transform: scale(0.9) rotate(-3deg); opacity: 0.6; filter: grayscale(0.5); }
            }
            .kotodama-screen-shake {
                animation: kotodama-shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
            }
            @keyframes kotodama-shake {
                0%, 100% { transform: translate(0, 0) rotate(0deg); }
                10%, 90% { transform: translate(-2px, -3px) rotate(-1deg); }
                20%, 80% { transform: translate(-4px, 0px) rotate(1deg); }
                30%, 70% { transform: translate(4px, 3px) rotate(0deg); }
                40%, 60% { transform: translate(2px, -2px) rotate(1deg); }
                50% { transform: translate(-2px, 3px) rotate(-1deg); }
            }
            .kotodama-flash::after {
                content: ""; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
                background: radial-gradient(circle at 50% 50%, rgba(120, 255, 198, 0.2) 0%, rgba(143, 38, 38, 0.15) 60%, transparent 100%);
                mix-blend-mode: hard-light; pointer-events: none; z-index: 99999;
                animation: k-flash 0.5s ease-out forwards;
            }
            @keyframes k-flash {
                0% { opacity: 0; transform: scale(0.9); }
                15% { opacity: 1; transform: scale(1.05); filter: contrast(1.5); }
                100% { opacity: 0; transform: scale(1); }
            }
        `;
        topDoc.head.appendChild(style);
    } catch (e) { console.error('[交互选项] 样式注入失败:', e); }
}

// --- 2. 智能填入与安全替换 ---
function smartReplaceOrAppend(newKeyword) {
    let textarea = document.getElementById('send_textarea');
    if (!textarea && window.top) textarea = window.top.document.getElementById('send_textarea');
    if (!textarea) return;

    textarea.focus();
    let currentVal = textarea.value || "";
    const replacementStr = `不是【${newKeyword}】而是……`;

    // 正则嗅探：精准寻找旧的改写句式
    const regex = /不是【.*?】而是……/g;

    let finalVal = "";
    if (regex.test(currentVal)) {
        // 无缝替换，保留玩家周围的描写文本
        finalVal = currentVal.replace(regex, replacementStr);
    } else {
        // 智能追加到末尾
        finalVal = currentVal.trim().length > 0 ? 
            (currentVal.endsWith('\n') ? (currentVal + replacementStr) : (currentVal + replacementStr)) : 
            replacementStr;
    }

    const nativeSetter = (window.HTMLTextAreaElement && Object.getOwnPropertyDescriptor)
        ? (Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, "value") || {}).set
        : null;
    if (nativeSetter) nativeSetter.call(textarea, finalVal);
    else textarea.value = finalVal;

    textarea.dispatchEvent(new Event('input', { bubbles: true }));
    textarea.dispatchEvent(new Event('change', { bubbles: true }));

    const len = finalVal.length;
    textarea.setSelectionRange(len, len);
    textarea.style.height = 'auto';
    textarea.style.height = (textarea.scrollHeight) + 'px';
    textarea.scrollTop = textarea.scrollHeight;
}

// --- 3. 全局点击处理 (单选与强制清理残影) ---
window.top.interactiveOptionClick_v12 = function(btn, encodedText) {
    const text = decodeURIComponent(encodedText);

    // 如果该按钮已经破碎，忽略点击
    if (btn.classList.contains('smashed')) return;

    // A. 恢复旧按钮 (单选复位机制)
    const doc = btn.ownerDocument || window.top.document;
    const allSmashed = doc.querySelectorAll('.interactive-option-btn.smashed');

    allSmashed.forEach(oldBtn => {
        if (oldBtn !== btn) {
            oldBtn.classList.remove('smashed'); // 移除碎裂状态

            // 尝试读取备份的纯净文本。如果没有备份，利用正则强行剥离“破”字和括号
            let raw = oldBtn.getAttribute('data-raw');
            if (!raw) {
                raw = oldBtn.textContent.replace(/破$/, '').replace(/^【/, '').replace(/】$/, '').trim();
            }

            // 恢复为最初始的纯净按钮状态
            oldBtn.textContent = raw; 
        }
    });

    // B. 当前按钮破碎特效
    btn.classList.add('smashed');
    btn.textContent = '【' + text + '】破'; 

    // C. 触发震动与闪光特效
    const targetShake = doc.body; 
    targetShake.classList.remove('kotodama-screen-shake', 'kotodama-flash'); 
    void targetShake.offsetWidth; // 强制重绘，确保动画连续触发
    targetShake.classList.add('kotodama-screen-shake', 'kotodama-flash');

    setTimeout(() => {
        targetShake.classList.remove('kotodama-screen-shake', 'kotodama-flash');
    }, 600);

    // D. 延迟高潮时刻，执行智能替换
    setTimeout(() => {
        smartReplaceOrAppend(text);
    }, 200);
};

// --- 4. 文本节点替换 (创建按钮) ---
function processElement(rootElement) {
    if (!rootElement || !rootElement.isConnected) return;
    const walker = document.createTreeWalker(
        rootElement, NodeFilter.SHOW_TEXT,
        {
            acceptNode: function(node) {
                if (!node.nodeValue.trim()) return NodeFilter.FILTER_SKIP;
                if (!node.nodeValue.includes('【')) return NodeFilter.FILTER_SKIP;
                const parentTag = node.parentNode.tagName.toLowerCase();
                if (['script', 'style', 'textarea', 'button', 'select', 'input'].includes(parentTag)) return NodeFilter.FILTER_REJECT;
                if (node.parentNode.classList.contains('interactive-option-btn')) return NodeFilter.FILTER_REJECT;
                return NodeFilter.FILTER_ACCEPT;
            }
        }, false
    );

    const nodesToReplace =[];
    while (walker.nextNode()) nodesToReplace.push(walker.currentNode);

    nodesToReplace.forEach(node => {
        const text = node.nodeValue;
        const fragment = document.createDocumentFragment();
        let lastIndex = 0, match;
        const regex = new RegExp(OPTION_REGEX.source, 'g');
        let hasReplacement = false;

        while ((match = regex.exec(text)) !== null) {
            hasReplacement = true;
            if (match.index > lastIndex) fragment.appendChild(document.createTextNode(text.substring(lastIndex, match.index)));

            const btn = document.createElement('button');
            btn.className = 'interactive-option-btn';
            btn.textContent = match[1]; // 呈现无括号的纯净字样
            btn.setAttribute('data-raw', match[1]); // 保存无污染原始文本
            btn.type = 'button';
            btn.title = '注入言灵，粉碎此怪谈法则';

            const safeText = encodeURIComponent(match[1]);
            btn.setAttribute('onclick', `window.top.interactiveOptionClick_v12(this, '${safeText}')`);

            fragment.appendChild(btn);
            lastIndex = regex.lastIndex;
        }

        if (hasReplacement) {
            if (lastIndex < text.length) fragment.appendChild(document.createTextNode(text.substring(lastIndex)));
            node.parentNode.replaceChild(fragment, node);
        }
    });
}

// --- 5. 扫描主入口 (多阶段渲染) ---
let debounceTimer = null;
function debouncedScan() {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
        injectStyles();

        let statData = {};
        try {
            const Mvu = window.Mvu || (window.parent && window.parent.Mvu) || (window.top && window.top.Mvu);
            if (Mvu && typeof Mvu.getMvuData === 'function') {
                const data = Mvu.getMvuData({ type: 'message', message_id: -1 });
                if (data && data.stat_data) statData = data.stat_data;
            }
        } catch(e) { console.warn("MVU 读取失败，使用默认状态"); }

        const getVal = (path, def) => (typeof _ !== 'undefined' && _.get) ? _.get(statData, path, def) : def;

        const phase = getVal('游戏状态.当前阶段', '日常');
        const isTutorialDone = getVal('游戏状态.新手引导已完成', false);

        // 更新条件：在 导入、怪谈、结算 或 新手入部时 均可交互
        const validPhases = ['导入', '怪谈', '结算'];
        const isTutorial = (phase === '日常' && isTutorialDone === false);
        const shouldRenderButtons = validPhases.includes(phase) || isTutorial;

        if (shouldRenderButtons) {
            $('.mes_text').each(function() { processElement(this); });
        } else {
            // 退回日常阶段后，全部按钮打回普通文本，强制清理可能存在的残影
            $('.interactive-option-btn').each(function() {
                const rawText = this.getAttribute('data-raw') || this.textContent.replace(/破$/, '').replace(/^【/, '').replace(/】$/, '').trim();
                const textNode = document.createTextNode('【' + rawText + '】');
                this.parentNode.replaceChild(textNode, this);
            });
        }
    }, SCAN_DELAY);
}

// --- 6. 事件监听 ---
function initListeners() {
    if (typeof eventOn !== 'undefined') {
        eventOn(tavern_events.MESSAGE_RECEIVED, debouncedScan);
        eventOn(tavern_events.CHAT_CHANGED, debouncedScan);
        eventOn(tavern_events.MESSAGE_UPDATED, debouncedScan);
    }
    const Mvu = window.Mvu || (window.parent && window.parent.Mvu) || (window.top && window.top.Mvu);
    if (Mvu && Mvu.events && typeof eventOn === 'function') {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, debouncedScan);
    }
    $(document).on('VARIABLE_UPDATE_ENDED', () => debouncedScan());
    debouncedScan();
}

$(() => { setTimeout(initListeners, 1000); });

/**
 * 角色卡 “怪谈社” 专属MVU监护脚本 (v11.0-NativePassThrough)
 * 核心逻辑：完全模仿魔法少女脚本，直接操作事件传递的原始对象引用。
 * 解决：Zod Schema Reconcile 回滚问题。
 */

const SCRIPT_NAME = '怪谈社监护脚本';
const SCRIPT_VERSION = 'v11.0-PassThrough';

// --- 1. 全局配置 ---

const RELATION_CONFIG = [
    { level: 0, cap: 20, reqStories: 1, eventKey: 'EVENT_突破_入部', hint: '她还在观察你是否有面对恐惧的力量。' },
    { level: 1, cap: 50, reqStories: 3, eventKey: 'EVENT_突破_交心', hint: '你们的关系止步于此，除非能共同跨越更多的危机。' },
    { level: 2, cap: 80, reqStories: 7, eventKey: 'EVENT_突破_共鸣', hint: '灵魂的共鸣需要绝对的信赖，还需要更多时间。' }
];

// 老师的配置
const SAE_RELATION_CONFIG = [
    { level: 0, cap: 30, reqStories: 2, eventKey: 'EVENT_沙绘_突破_往事', hint: '她依然把你当成需要远离麻烦的小鬼。' },
    { level: 1, cap: 60, reqStories: 5, eventKey: 'EVENT_沙绘_突破_回避', hint: '大人的防线非常坚固，必须证明你拥有活下去的实力。' },
    { level: 2, cap: 90, reqStories: 8, eventKey: 'EVENT_沙绘_突破_救赎', hint: '过去的创伤让她不敢再往前走一步。' }
];

const scriptState = {
    initialized: false,
    retryCount: 0,
    maxRetries: 10,
    listeners: { onVariableUpdateEnded: null },
    previousData: null,
    isWriting: false
};

// --- 2. 基础交互层 ---

function getMvuInstance() {
    try {
        if (window.top && window.top.Mvu) return window.top.Mvu;
        return window.Mvu || null;
    } catch { return window.Mvu || null; }
}

/**
 * 不再尝试获取 Live Data，也不再构造新对象。
 * 直接提交我们刚刚修改过的 originalVariables 对象。
 */
async function commitChanges(variables) {
    if (scriptState.isWriting) return;

    // 只有当数据真的变了 (我们在 Logic Pipeline 里修改了 variables.stat_data)，才提交
    // 这里我们假设如果 Logic 运行了且有 set 操作，数据就已经变了
    // 为了防止死循环，我们依然做一个简单的检查

    // 获取 MVU 实例
    const Mvu = getMvuInstance();
    if (!Mvu) return;

    scriptState.isWriting = true;
    console.log(`[${SCRIPT_NAME}] 💾 Passing-through changes to MVU...`);

    try {
        // [核心] 直接把传入的 variables 原路送回
        // 这样保留了所有的 hidden properties 和 metadata，让 Zod 以为无事发生
        await Mvu.replaceMvuData(variables, { type: 'message', message_id: -1 });
        console.log(`[${SCRIPT_NAME}] ✅ Commit success.`);

        // 广播事件
        if (Mvu.events && Mvu.events.VARIABLE_UPDATE_ENDED) {
            // 广播时可以 Clone 一份，避免引用污染 UI
            const payload = { stat_data: JSON.parse(JSON.stringify(variables.stat_data)) };
            if (window.top && window.top.$) {
                window.top.$(window.top.document).trigger({ type: Mvu.events.VARIABLE_UPDATE_ENDED, detail: payload });
            }
        }
    } catch (e) {
        console.error(`[${SCRIPT_NAME}] Commit Error:`, e);
    } finally {
        scriptState.isWriting = false;
    }
}

// --- 3. 工具函数 ---

// 辅助：直接修改 variables 对象内部
function applyAssign(variables, path, value) {
    const fullPath = `stat_data.${path}`;
    let arr = _.get(variables, fullPath);

    if (!Array.isArray(arr)) {
        arr = arr ? [arr] : [];
        _.set(variables, fullPath, arr);
    }

    // 查重
    const exists = arr.some(item => {
        const t1 = (typeof item === 'object' && item.标题) ? item.标题 : item;
        const t2 = (typeof value === 'object' && value.标题) ? value.标题 : value;
        return t1 === t2;
    });

    if (!exists) {
        arr.push(value);
        console.log(`[${SCRIPT_NAME}] ➕ Added to [${path}]:`, value);
        // 因为 arr 是引用，push 已经改变了原对象，但为了保险 set 回去
        _.set(variables, fullPath, arr); 
        return true; // 返回 true 表示发生了修改
    }
    return false;
}

function applySet(variables, path, value) {
    const fullPath = `stat_data.${path}`;
    const current = _.get(variables, fullPath);
    if (!_.isEqual(current, value)) {
        _.set(variables, fullPath, value);
        // console.log(`[${SCRIPT_NAME}] ✏️ Set [${path}]`);
        return true; // 返回 true 表示发生了修改
    }
    return false;
}

// --- 4. 业务逻辑---

function runLogicPipeline(variables, prevStatData) {
    let hasChanged = false;

    // --- A. Guard ---
    // 结构补全
    if (!_.get(variables, 'stat_data.白物语注册表')) { _.set(variables, 'stat_data.白物语注册表', {}); hasChanged = true; }
    if (!_.get(variables, 'stat_data.系统状态')) { _.set(variables, 'stat_data.系统状态', { 待处理事件: {} }); hasChanged = true; }
    if (!_.get(variables, 'stat_data.档案库.已完成怪谈')) { _.set(variables, 'stat_data.档案库.已完成怪谈', {}); hasChanged = true; }

    // 好感度锁定
    // 绮罗香的钳制
    const favorPath = '角色状态.白川绮罗香.好感度';
    let favor = _.get(variables, `stat_data.${favorPath}`, 0);
    const level = _.get(variables, 'stat_data.角色状态.白川绮罗香.好感度等级', 0);

    if (favor < 0) { applySet(variables, favorPath, 0); favor = 0; hasChanged = true; }
    if (favor > 100) { applySet(variables, favorPath, 100); favor = 100; hasChanged = true; }

    // 等级锁
    if (level < RELATION_CONFIG.length) {
        const cap = RELATION_CONFIG[level].cap;
        if (favor > cap) {
            console.log(`[${SCRIPT_NAME}] 🔒 Locking Favor ${favor} -> ${cap}`);
            if (applySet(variables, favorPath, cap)) hasChanged = true;
        }
    }

    // 沙绘的钳制
    const saeFavorPath = '角色状态.绪川沙绘.好感度';
    let saeFavor = _.get(variables, `stat_data.${saeFavorPath}`, 0);
    const saeLevel = _.get(variables, 'stat_data.角色状态.绪川沙绘.好感度等级', 0);

    if (saeFavor < 0) { applySet(variables, saeFavorPath, 0); saeFavor = 0; hasChanged = true; }
    if (saeFavor > 100) { applySet(variables, saeFavorPath, 100); saeFavor = 100; hasChanged = true; }

    if (saeLevel < SAE_RELATION_CONFIG.length) {
        const saeCap = SAE_RELATION_CONFIG[saeLevel].cap;
        if (saeFavor > saeCap) {
            console.log(`[${SCRIPT_NAME}] 🔒 Locking Sae Favor ${saeFavor} -> ${saeCap}`);
            if (applySet(variables, saeFavorPath, saeCap)) hasChanged = true;
        }
    }

// --- B. Reactive ---
    const curPhase = _.get(variables, 'stat_data.游戏状态.当前阶段');
    const prevPhase = _.get(prevStatData, '游戏状态.当前阶段');

    // --- C. Proactive ---
    // 日常清理 (回到日常后，脚本会自动清理过期的临时状态)
    if (curPhase === '日常' && prevPhase !== '日常') {
        console.log(`[${SCRIPT_NAME}] ☀️ Daily Reset`);
        if (applySet(variables, '游戏状态.当前怪谈标题', '无')) hasChanged = true;
        if (applySet(variables, '白物语注册表', {})) hasChanged = true;

        const events = _.get(variables, 'stat_data.系统状态.待处理事件', {});
        const keeps = ['EVENT_突破_入部', 'EVENT_突破_交心', 'EVENT_突破_共鸣'];
        const cleaned = _.pick(events, keeps);
        if (Object.keys(events).length !== Object.keys(cleaned).length) {
            applySet(variables, '系统状态.待处理事件', cleaned);
            hasChanged = true;
        }
    }

    // 导入回蓝 (保底机制：进入新怪谈导入阶段时，若灵力不满则自动回满)
    if (curPhase === '导入' && prevPhase !== '导入') {
        const mp = _.get(variables, 'stat_data.玩家状态.灵力');
        if (mp < 5) {
            if (applySet(variables, '玩家状态.灵力', 5)) hasChanged = true;
        }
        if (applySet(variables, '白物语注册表', {})) hasChanged = true;
    }

    // --- D. 事件推送 ---
    if (level < RELATION_CONFIG.length) {
        const cfg = RELATION_CONFIG[level];
        const f = _.get(variables, `stat_data.${favorPath}`, 0);
        const solved = Object.keys(_.get(variables, 'stat_data.档案库.已完成怪谈', {})).length;
        const evs = _.get(variables, 'stat_data.系统状态.待处理事件', {});

        if (f >= cfg.cap && curPhase === '日常' && !evs[cfg.eventKey]) {
            if (solved >= cfg.reqStories) {
                console.log(`[${SCRIPT_NAME}] 🎉 Event: ${cfg.eventKey}`);
                if (applySet(variables, `系统状态.待处理事件.${cfg.eventKey}`, true)) hasChanged = true;
                if (evs['系统_好感瓶颈']) {
                    const e = _.omit(evs, ['系统_好感瓶颈']);
                    if (applySet(variables, '系统状态.待处理事件', e)) hasChanged = true;
                }
            } else if (!evs['系统_好感瓶颈']) {
                if (applySet(variables, '系统状态.待处理事件.系统_好感瓶颈', cfg.hint)) hasChanged = true;
            }
        }
    }

    if (saeLevel < SAE_RELATION_CONFIG.length) {
        const s_cfg = SAE_RELATION_CONFIG[saeLevel];
        const s_f = _.get(variables, `stat_data.${saeFavorPath}`, 0);
        const solved = Object.keys(_.get(variables, 'stat_data.档案库.已完成怪谈', {})).length;
        const evs = _.get(variables, 'stat_data.系统状态.待处理事件', {});

        if (s_f >= s_cfg.cap && curPhase === '日常' && !evs[s_cfg.eventKey]) {
            if (solved >= s_cfg.reqStories) {
                console.log(`[${SCRIPT_NAME}] ☕ Event: ${s_cfg.eventKey}`);
                if (applySet(variables, `系统状态.待处理事件.${s_cfg.eventKey}`, true)) hasChanged = true;
                if (evs['系统_沙绘瓶颈']) {
                    const e = _.omit(evs, ['系统_沙绘瓶颈']);
                    if (applySet(variables, '系统状态.待处理事件', e)) hasChanged = true;
                }
            } else if (!evs['系统_沙绘瓶颈']) {
                if (applySet(variables, '系统状态.待处理事件.系统_沙绘瓶颈', s_cfg.hint)) hasChanged = true;
            }
        }
    }

    return hasChanged;
}

// --- 5. 主事件循环 ---

async function onVariableUpdateEnded(eventData) {
    // 1. 获取数据 (优先使用事件传递的对象)
    // 魔法少女脚本的核心在于：它相信这个 eventData (variables) 就是它要修改的那个对象
    let variables = eventData;

    // 如果没有，尝试兜底
    if (!variables || !variables.stat_data) {
        const Mvu = getMvuInstance();
        variables = Mvu ? Mvu.getMvuData({ type: 'message', message_id: -1 }) : null;
    }

    if (!variables || !variables.stat_data) return;

    // 2. 初始化快照 (Deep Clone 用于对比，不用于修改)
    if (!scriptState.previousData) {
        scriptState.previousData = JSON.parse(JSON.stringify(variables.stat_data));
        console.log(`[${SCRIPT_NAME}] Init Snapshot.`);
        return;
    }

    console.log(`[${SCRIPT_NAME}] ----- Turn Start -----`);

    // 3. 执行逻辑
    // 关键区别：我们把 variables 直接传进去，让 Logic 函数修改它内部的属性
    const hasChanged = runLogicPipeline(variables, scriptState.previousData);

    // 4. 提交
    // 只有当 runLogicPipeline 返回 true (确实发生了修改) 时才提交
    if (hasChanged) {
        await commitChanges(variables);
    } else {
        // console.log(`[${SCRIPT_NAME}] No changes needed.`);
    }

    const cur = variables.stat_data['游戏状态']['当前阶段'];

    const prevPhase = scriptState.previousData && scriptState.previousData['游戏状态']['当前阶段'];
    if (prevPhase && cur !== prevPhase) {
        console.log(`[${SCRIPT_NAME}] 阶段切换: ${prevPhase} → ${cur}`);
     }

    // 5. 更新快照 (Deep Clone)
    scriptState.previousData = JSON.parse(JSON.stringify(variables.stat_data));

    console.log(`[${SCRIPT_NAME}] ----- Turn End -----`);
}

// --- 6. 启动 ---

function initialize() {
    if (scriptState.initialized) return;
    const Mvu = getMvuInstance();
    if (Mvu) {
        scriptState.listeners.onVariableUpdateEnded = onVariableUpdateEnded;
        // 优先使用 eventOn
        if (typeof eventOn === 'function') {
            eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, scriptState.listeners.onVariableUpdateEnded);
        } else {
            $(document).on(Mvu.events.VARIABLE_UPDATE_ENDED, (e, d) => onVariableUpdateEnded(d || e.detail));
        }
        scriptState.initialized = true;
        console.log(`[${SCRIPT_NAME}] ${SCRIPT_VERSION} Active.`);
        if (window.toastr) toastr.success(`${SCRIPT_NAME} Active`, 'System');
    } else {
        scriptState.retryCount++;
        if (scriptState.retryCount < 10) setTimeout(initialize, 1000);
    }
}

function cleanup() {
    const Mvu = getMvuInstance();
    if (Mvu && scriptState.listeners.onVariableUpdateEnded) {
        if (typeof eventRemoveListener === 'function') eventRemoveListener(Mvu.events.VARIABLE_UPDATE_ENDED, scriptState.listeners.onVariableUpdateEnded);
        else $(document).off(Mvu.events.VARIABLE_UPDATE_ENDED);
    }
}

$(() => { cleanup(); setTimeout(initialize, 1500); });
$(window).on('unload', cleanup);
